function mopts(PDO $pdo,string $table,string $expr):array{
 $allowed=['clients','businesses','users','lead_sources','pipeline_stages','product_categories','service_categories','services','workflow_templates','automation_rules','departments'];
 if(!in_array($table,$allowed,true))return[];
 try{return $pdo->query("SELECT id,$expr label FROM `$table` ORDER BY label LIMIT 500")->fetchAll();}catch(Throwable $e){return[];}
}
if($fields && $_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=post_string('action');$id=post_int('id');
 try{
  if($action==='delete'&&$id){$pdo->prepare("DELETE FROM `$table` WHERE id=?")->execute([$id]);activity($pdo,'delete',$entity,$id,'Record deleted');flash('success','Record deleted.');redirect('module.php?entity='.rawurlencode($entity));}
  if($action==='save'){
   $data=[];foreach($fields as $n=>$f){$v=$_POST[$n]??null;if($f[1]==='check')$v=isset($_POST[$n])?1:0;if(is_string($v))$v=trim($v);if($v==='')$v=null;if($f[4]&&$v===null)throw new RuntimeException($f[0].' is required.');if($entity==='secure-data'&&$n==='encrypted_value'&&$v!==null)$v=sps_encrypt($v);$data[$n]=$v;}
   if($id){$set=[];$p=[];foreach($data as $k=>$v){$set[]="`$k`=?";$p[]=$v;}$p[]=$id;$pdo->prepare("UPDATE `$table` SET ".implode(',',$set).' WHERE id=?')->execute($p);activity($pdo,'update',$entity,$id,'Record updated');}
   else{$cols=array_keys($data);$pdo->prepare("INSERT INTO `$table` (`".implode('`,`',$cols)."`) VALUES (".implode(',',array_fill(0,count($cols),'?')).")")->execute(array_values($data));$id=(int)$pdo->lastInsertId();activity($pdo,'create',$entity,$id,'Record created');}
   flash('success','Record saved.');redirect('module.php?entity='.rawurlencode($entity));
  }
 }catch(Throwable $e){$err=$e->getMessage();error_log('[SPS MODULE] '.$e->getMessage());}
}
$editId=(int)($_GET['edit_id']??0);$edit=[];if($editId){$s=$pdo->prepare("SELECT * FROM `$table` WHERE id=?");$s->execute([$editId]);$edit=$s->fetch()?:[];}
$q=trim((string)($_GET['q']??''));$rows=[];
if($q&&$fields){$search=[];$p=[];foreach($fields as $n=>$f)if(in_array($f[1],['text','email','area'],true)){$search[]="`$n` LIKE ?";$p[]='%'.$q.'%';}if($search){$s=$pdo->prepare("SELECT * FROM `$table` WHERE ".implode(' OR ',$search)." ORDER BY id DESC LIMIT 200");$s->execute($p);$rows=$s->fetchAll();}else{$rows=$pdo->query("SELECT * FROM `$table` ORDER BY id DESC LIMIT 200")->fetchAll();}}
else{$rows=$pdo->query("SELECT * FROM `$table` ORDER BY id DESC LIMIT 200")->fetchAll();}
